INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~は ~です', '~은/는 ~입니다', '명사 + は + 명사 + です', '[{"jp": "私は学生です。", "ko": "저는 학생입니다."}, {"jp": "これは本です。", "ko": "이것은 책입니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~の', '~의 (소유/관계/속성)', '명사 + の + 명사', '[{"jp": "私のカバンです。", "ko": "저의 가방입니다."}, {"jp": "日本語の先生です。", "ko": "일본어 선생님입니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~も', '~도 (첨가/병렬)', '명사 + も', '[{"jp": "私も行きます。", "ko": "저도 갑니다."}, {"jp": "これも美味しいです。", "ko": "이것도 맛있습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~にあります/います', '~에 있습니다 (존재)', '장소 + に + あります/います', '[{"jp": "本屋はあそこにあります。", "ko": "서점은 저기에 있습니다."}, {"jp": "猫は部屋にいます。", "ko": "고양이는 방에 있습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~へ行きます/来ます', '~에 가다/오다 (방향)', '장소 + へ + 行きます/来ます', '[{"jp": "学校へ行きます。", "ko": "학교에 갑니다."}, {"jp": "日本へ来ました。", "ko": "일본에 왔습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~を', '~을/를 (목적)', '명사 + を', '[{"jp": "水を飲みます。", "ko": "물을 마십니다."}, {"jp": "ご飯を食べます。", "ko": "밥을 먹습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~で', '~에서(장소) / ~으로(수단/도구)', '명사 + で', '[{"jp": "図書館で勉強します。", "ko": "도서관에서 공부합니다."}, {"jp": "バスで行きます。", "ko": "버스로 갑니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~と', '~와/과 (병렬/동반)', '명사 + と', '[{"jp": "友達と会います。", "ko": "친구와 만듭니다."}, {"jp": "パンとミルク。", "ko": "빵과 우유."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~から ~まで', '~부터 ~까지 (시작/끝)', '명사 + から + 명사 + まで', '[{"jp": "9時から5時まで。", "ko": "9시부터 5시까지."}, {"jp": "ここから駅まで。", "ko": "여기서 역까지."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~에', '~에 (시간/장소)', '명사 + に', '[{"jp": "日曜日に会います。", "ko": "일요일에 만납니다."}, {"jp": "部屋にあります。", "ko": "방에 있습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~てください', '~해주세요 (의뢰)', 'V(て형) + ください', '[{"jp": "座ってください。", "ko": "앉아 주세요."}, {"jp": "나에게 보여주세요.", "ko": "보여주세요."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~てはいけません', '~해서는 안 됩니다 (금지)', 'V(て형) + はいけません', '[{"jp": "ここでタバコを吸ってはいけません。", "ko": "여기서 담배를 피워서는 안 됩니다."}, {"jp": "テレビを見てはいけません。", "ko": "TV를 봐서는 안 됩니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~てもいいです', '~해도 좋습니다 (허가)', 'V(て형) + もいいです', '[{"jp": "入ってもいいです。", "ko": "들어와도 좋습니다."}, {"jp": "食べてもいいです。", "ko": "먹어도 좋습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~ています', '~하고 있습니다 (진행/상태)', 'V(て형) + います', '[{"jp": "今勉強しています。", "ko": "지금 공부하고 있습니다."}, {"jp": "テレビを見ています。", "ko": "TV를 보고 있습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~たいです', '~하고 싶습니다 (희망)', 'V(ます형 중지형) + たいです', '[{"jp": "寿司を食べたいです。", "ko": "초밥을 먹고 싶습니다."}, {"jp": "日本に行きたいです。", "ko": "일본에 가고 싶습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~ないでください', '~하지 마세요 (금지/요청)', 'V(ない형) + でください', '[{"jp": "忘れないでください。", "ko": "잊지 마세요."}, {"jp": "入らないでください。", "ko": "들어가지 마세요."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~なければなりません', '~해야 합니다 (의무)', 'V(ない형) + なければなりません', '[{"jp": "学校へ行かなければなりません。", "ko": "학교에 가야 합니다."}, {"jp": "宿題をしなければなりません。", "ko": "숙제를 해야 합니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~なくてもいいです', '~하지 않아도 됩니다 (불필요)', 'V(ない형) + なくてもいいです', '[{"jp": "明日は来なくてもいいです。", "ko": "내일은 오지 않아도 됩니다."}, {"jp": "急がなくてもいいです。", "ko": "서두르지 않아도 됩니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~ましょう', '~합시다 (권유)', 'V(ます형 중지형) + ましょう', '[{"jp": "一緒に帰りましょう。", "ko": "함께 돌아갑시다."}, {"jp": "少し休みましょう。", "ko": "조금 쉽시다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~ましょうか', '~할까요? (권유/도움)', 'V(ます형 중지형) + ましょうか', '[{"jp": "一緒に行きましょうか。", "ko": "함께 갈까요?"}, {"jp": "手伝いましょうか。", "ko": "도와드릴까요?"}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~ながら', '~하면서 (동시 행위)', 'V(ます형 중지형) + ながら', '[{"jp": "音楽を聞きながら勉強합니다。", "ko": "음악을 들으면서 공부합니다."}, {"jp": "歩きながら話しましょう。", "ko": "걸으면서 이야기합시다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~たことがあります', '~한 적이 있습니다 (경험)', 'V(た형) + ことがあります', '[{"jp": "日本に行ったことがあります。", "ko": "일본에 간 적이 있습니다."}, {"jp": "納豆を食べたことがあります。", "ko": "낫또를 먹은 적이 있습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~ほうがいいです', '~하는 편이 좋습니다 (충고)', 'V(た형) + ほうがいいです', '[{"jp": "早く寝たほうがいい입니다。", "ko": "일찍 자는 편이 좋습니다."}, {"jp": "病院へ行ったほうがいい입니다。", "ko": "병원에 가는 편이 좋습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~たり ~たり します', '~하거나 ~하거나 (나열)', 'V(た형) + り + V(た형) + り します', '[{"jp": "休みはテレビを見たり、本を読んだりします。", "ko": "주말에는 TV를 보거나 책을 읽거나 합니다."}, {"jp": "掃除したり、洗濯したりしました。", "ko": "청소를 하거나 빨래를 하거나 했습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~と思います', '~라고 생각합니다 (의견/추측)', '보통형 + と思います', '[{"jp": "日本語は難しいと思います。", "ko": "일본어는 어렵다고 생각합니다."}, {"jp": "友達が来ると思います。", "ko": "친구가 올 것이라고 생각합니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~と言いました', '~라고 말했습니다 (인용)', '보통형 + と言いました', '[{"jp": "先生は「宿題です」と言いました。", "ko": "선생님은 「숙제입니다」라고 말했습니다."}, {"jp": "彼は「行きます」と言いました。", "ko": "그는 「갑니다」라고 말했습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~でしょう', '~이겠지요 (추측/확인)', '보통형 + でしょう', '[{"jp": "明日は雨でしょう。", "ko": "내일은 비가 오겠지요."}, {"jp": "これ、美味しいでしょう?", "ko": "이거 맛있죠?"}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~かもしれません', '~할지도 모릅니다 (추측)', '보통형 + かもしれません', '[{"jp": "明日は暇かもしれません。", "ko": "내일은 한가할지도 모릅니다."}, {"jp": "彼は来ないかもしれません。", "ko": "그는 오지 않을지도 모릅니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~そうです', '~해 보입니다 (양태)', 'Adj(어간) + そうです', '[{"jp": "このケーキは美味しそうですね。", "ko": "이 케이크는 맛있어 보이네요."}, {"jp": "雨が降りそうですね。", "ko": "비가 올 것 같네요."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('まえに', '~하기 전에 (시간 순서)', 'V(사전형)/명사+の + まえに', '[{"jp": "寝る前に薬を飲みます。", "ko": "자기 전에 약을 먹습니다."}, {"jp": "食事の前に手を洗います。", "ko": "식사 전에 손을 씻습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('あとに', '~한 후에 (시간 순서)', 'V(た형)/명사+の + あとに', '[{"jp": "仕事のあとに飲みに行きます。", "ko": "업무 후에 마시러 갑니다."}, {"jp": "聞いたあとに答えてください。", "ko": "들은 후에 대답해 주세요."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('とき', '~할 때 (시간)', '보통형 / 명사+の + とき', '[{"jp": "ご飯を食べる時、「いただきます」と言います。", "ko": "밥을 먹을 때 \"잘 먹겠습니다\"라고 말합니다."}, {"jp": "子供の時、よく泳ぎました。", "ko": "어릴 때 자주 수영했습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('から / ので', '~때문에/해서 (이유/원인)', '보통형 + から / ので', '[{"jp": "疲れているから休みます。", "ko": "피곤하기 때문에 쉽니다."}, {"jp": "雨が降ったので遅れました。", "ko": "비가 와서 늦었습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~が', '~하지만 (역접/배경)', '문장 + が', '[{"jp": "勉強은 힘들지만 즐겁습니다.", "ko": "공부는 힘들지만 즐겁습니다."}, {"jp": "失礼ですが、お名前は?", "ko": "실례지만 성함이 어떻게 되세요?"}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~より', '~보다 (비교)', '명사 + より', '[{"jp": "昨日より暑いです。", "ko": "어제보다 덥습니다."}, {"jp": "飛行機のほうが新幹線より速いです。", "ko": "비행기가 신칸센보다 빠릅니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('くらい / ほど', '~정도 (수량/정도)', '명사/수량 + くらい / ほど', '[{"jp": "30分くらいかかります。", "ko": "30분 정도 걸립니다."}, {"jp": "リンゴを三つほど買いました。", "ko": "사과를 세 개 정도 샀습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('だけ', '~만 (한정)', '명사 + だけ', '[{"jp": "水だけ飲みます。", "ko": "물만 마십니다."}, {"jp": "私だけ行きませんでした。", "ko": "저만 가지 않았습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('しか ~ない', '~밖에 ~않다 (한정 강조)', '명사 + しか + 부정형', '[{"jp": "千円しかありません。", "ko": "천 엔밖에 없습니다."}, {"jp": "一人しか来ませんでした。", "ko": "한 명밖에 안 왔습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('ごろ', '~쯤 (시간 추정)', '시간 + ごろ', '[{"jp": "五時ごろに行きます。", "ko": "5시쯤에 갑니다."}, {"jp": "夜十時ごろ寝ます。", "ko": "밤 10시쯤 잡니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~をください', '~주세요 (사물 요청)', '명사 + を + ください', '[{"jp": "水をください。", "ko": "물 주세요."}, {"jp": "これをください。", "ko": "이것을 주세요."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('ことができます', '~할 수 있습니다 (가능)', 'V(사전형) + ことができます', '[{"jp": "泳ぐことができます。", "ko": "수영을 할 수 있습니다."}, {"jp": "ピアノを弾くことができます。", "ko": "피아노를 칠 수 있습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('つもりです', '~할 작정입니다 (의지/계획)', 'V(사전형) + つもりです', '[{"jp": "明日早く起きるつもりです。", "ko": "내일 일찍 일어날 작정입니다."}, {"jp": "夏休みは旅行に行くつもりです。", "ko": "여름방학에는 여행을 갈 작정입니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('の / こと', '~하는 것 (명사화)', 'V(사전형) + の / こと', '[{"jp": "歌を聞くのが好きです。", "ko": "노래를 듣는 것을 좋아합니다."}, {"jp": "絵を描くことは楽しいです。", "ko": "그림을 그리는 것은 즐겁습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('なる', '~해지다 (상태 변화)', 'Adj(い->く)/Adj(나->に) + なる', '[{"jp": "寒くなりました。", "ko": "추워졌습니다."}, {"jp": "日本語が上手になりました。", "ko": "일본어를 잘하게 되었습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('て あげる/くれる/もらう', '~해 주다/받다 (수수)', 'V(て형) + 수수보조동사', '[{"jp": "友達に日本語を教えてあげました。", "ko": "친구에게 일본어를 가르쳐 주었습니다."}, {"jp": "母に本を買ってもらいました。", "ko": "어머니가 책을 사 주셨습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('ようです', '~인 것 같습니다 (추측/비유)', '보통형 / 명사+の + ようです', '[{"jp": "雨が降るようです。", "ko": "비가 올 것 같습니다."}, {"jp": "雪のようです。", "ko": "눈인 것 같습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('て / くて / で', '~해서/~하고 (순차/이유)', 'V(て) / Adi(い->くて) / Adj(な->で)', '[{"jp": "宿題をして寝ます。", "ko": "숙제를 하고 잡니다."}, {"jp": "この部屋は広くて綺麗です。", "ko": "이 방은 넓고 깨끗합니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('に 行きます/来ます', '~하러 가다/오다 (목적)', 'V(ます형) + に + 이동V', '[{"jp": "勉強しに図書館へ行きます。", "ko": "공부하러 도서관에 갑니다."}, {"jp": "ご飯を食べにレストランへ行きます。", "ko": "밥을 먹으러 레스토랑에 갑니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~やすい', '~하기 쉽다', 'V(ます형) + やすい', '[{"jp": "このペンは書きやすいです。", "ko": "이 펜은 쓰기 쉽습니다."}, {"jp": "この本は読みやすいです。", "ko": "이 책은 읽기 쉽습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~にくい', '~하기 어렵다', 'V(ます형) + にくい', '[{"jp": "この漢字は覚えにくいです。", "ko": "이 한자는 외우기 어렵습니다."}, {"jp": "この肉は食べにくいです。", "ko": "이 고기는 먹기 어렵습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~始める', '~하기 시작하다', 'V(ます형) + 始める', '[{"jp": "雨が降り始めました。", "ko": "비가 내리기 시작했습니다."}, {"jp": "食べ始めましょう。", "ko": "먹기 시작합시다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('上手です', '잘하다', '명사 + が + 上手です', '[{"jp": "日本語が上手ですね。", "ko": "일본어를 잘하시네요."}, {"jp": "料理が上手です。", "ko": "요리를 잘합니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('下手です', '못하다', '명사 + 가 + 下手です', '[{"jp": "歌が下手です。", "ko": "노래를 못합니다."}, {"jp": "テニスが下手です。", "ko": "테니스를 못합니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('好きです', '좋아하다', '명사 + 가 + 好きです', '[{"jp": "リンゴが好きです。", "ko": "사과를 좋아합니다."}, {"jp": "旅行が好きです。", "ko": "여행을 좋아합니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('嫌いです', '싫어하다', '명사 + 가 + 嫌いです', '[{"jp": "タバコが嫌いです。", "ko": "담배를 싫어합니다."}, {"jp": "寒いのが嫌いです。", "ko": "추운 것을 싫어합니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~のほうが', '~의 쪽이 (비교 우위)', '명사+のほうが', '[{"jp": "夏より冬のほうが好きです。", "ko": "여름보다 겨울을 더 좋아합니다."}, {"jp": "コーヒーのほうが安いです。", "ko": "커피 쪽이 더 쌉니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~も ~も', '~도 ~도', '명사 + も + 명사 + も', '[{"jp": "猫も犬もいます。", "ko": "고양이도 개도 있습니다."}, {"jp": "お茶も水も飲みました。", "ko": "차도 복도 마셨습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('といいます', '~라고 합니다', '명사 + といいます', '[{"jp": "これは日本語で何といいますか?", "ko": "이것은 일본어로 무엇이라고 합니까?"}, {"jp": "あの人は田中さんといいます。", "ko": "저 사람은 다나카 씨라고 합니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~か ~か', '~입니까 ~입니까 (선택)', '명사+か+명사+か', '[{"jp": "明日か明後日に行きます。", "ko": "내일이나 모레 갑니다."}, {"jp": "コーヒーか紅茶を飲みましょう。", "ko": "커피나 홍차를 마십시다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('上 / 下 / 中 / 外', '위치 관계', '명사+の+위치', '[{"jp": "机の上にあります。", "ko": "책상 위에 있습니다."}, {"jp": "カバンの中にあります。", "ko": "가방 안에 있습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('どうやって', '어떻게 (수단/방법)', '의문사', '[{"jp": "駅までどうやって行きますか?", "ko": "역까지 어떻게 갑니까?"}, {"jp": "これはどうやって食べますか?", "ko": "이것은 어떻게 먹습니까?"}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('いくらですか', '얼마입니까 (가격)', '의문사', '[{"jp": "これはいくらですか?", "ko": "이것은 얼마입니까?"}, {"jp": "全部でいくらですか?", "ko": "전부 얼마입니까?"}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~人', '사람 명수', '숫자 + 人', '[{"jp": "私の家族は四人です。", "ko": "저희 가족은 네 명입니다."}, {"jp": "学生が二十人います。", "ko": "학생이 20명 있습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~歳', '나이', '숫자 + 歳', '[{"jp": "私は二十歳です。", "ko": "저는 스무 살입니다."}, {"jp": "妹は十歳です。", "ko": "동생은 열 살입니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~つ', '사물 개수', '숫자 + つ', '[{"jp": "リンゴを三つ買いました。", "ko": "사과를 세 개 샀습니다."}, {"jp": "椅子がつあります。", "ko": "의자가 한 개 있습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~枚', '얇은 물건 개수', '숫자 + 枚', '[{"jp": "シャツが五枚あります。", "ko": "셔츠가 다섯 장 있습니다."}, {"jp": "切符を二枚買いました。", "ko": "표를 두 장 샀습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~回', '횟수', '숫자 + 回', '[{"jp": "一日に三回食べます。", "ko": "하루에 세 번 먹습니다."}, {"jp": "日本に二回行きました。", "ko": "일본에 두 번 갔습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~年生', '~학년', '숫자 + 年生', '[{"jp": "私は一年生です。", "ko": "저는 1학년입니다."}, {"jp": "弟は五年生です。", "ko": "동생은 5학년입니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~時 / ~分', '시간 표현', '숫자 + 時 / 分', '[{"jp": "今何時ですか?", "ko": "지금 몇 시입니까?"}, {"jp": "九時十五分です。", "ko": "9시 15분입니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('しかし', '하지만 (접속사)', '접속사', '[{"jp": "冬は寒いです。しかし、好きです。", "ko": "겨울은 춥습니다. 하지만 좋아합니다."}, {"jp": "雨が降りました。しかし、行きます。", "ko": "비가 왔습니다. 하지만 갑니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('そして', '그리고 (접속사)', '접속사', '[{"jp": "本を買いました。そして読みました。", "ko": "책을 샀습니다. 그리고 읽었습니다."}, {"jp": "花が咲きました。そして鳥が鳴きました。", "ko": "꽃이 피었습니다. 그리고 새가 울었습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('それで', '그래서 (접속사)', '접속사', '[{"jp": "疲れていました。それで早く寝ました。", "ko": "피곤했습니다. 그래서 일찍 잤습니다."}, {"jp": "雨でした。それで来ませんでした。", "ko": "비였습니다. 그래서 오지 않았습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('ところで', '그런데 (화제 전환)', '접속사', '[{"jp": "いい天気ですね。ところで、お元気ですか?", "ko": "좋은 날씨네요. 그런데 잘 지내시나요?"}, {"jp": "日本語が上手ですね。ところで、どこで習いましたか?", "ko": "일본어를 잘하시네요. 그런데 어디서 배우셨나요?"}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('なに / なん', '무엇 (의문사)', '의문사', '[{"jp": "これは何ですか?", "ko": "이것은 무엇입니까?"}, {"jp": "何を食べましたか?", "ko": "무엇을 먹었습니까?"}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('どこ / だれ', '어디 / 누구 (의문사)', '의문사', '[{"jp": "トイレはどこですか?", "ko": "화장실은 어디입니까?"}, {"jp": "あの人は誰ですか?", "ko": "저 사람은 누구입니까?"}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('いつ / どのくらい', '언제 / 얼마나 (의문사)', '의문사', '[{"jp": "試験はいつですか?", "ko": "시험은 언제입니까?"}, {"jp": "どのくらいかかりますか?", "ko": "얼마나 걸립니까?"}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('あげる / くれる / もらう', '주다 / 받다 (수수)', '명사+を+수수동사', '[{"jp": "友達に本をあげました。", "ko": "친구에게 책을 주었습니다."}, {"jp": "母に時計をもらいました。", "ko": "어머니께 시계를 받았습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~日 / ~月', '날짜 표현', '숫자 + 日 / 月', '[{"jp": "今日は何日ですか?", "ko": "오늘은 며칠입니까?"}, {"jp": "誕生日は五月三日です。", "ko": "생일은 5월 3일입니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('みたいな / みたいに', '~같은 / ~처럼 (비유)', '명사 + みたい', '[{"jp": "子供みたいな人です。", "ko": "아이 같은 사람입니다."}, {"jp": "雪みたいに白いです。", "ko": "눈처럼 하얗습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('予定です', '~할 예정입니다', 'V(사전형)/명사+の + 予定', '[{"jp": "明日行く予定です。", "ko": "내일 갈 예정입니다."}, {"jp": "出張の予定です。", "ko": "출장의 예정입니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('せる / させる', '사역동사 (보통형)', 'V(내이형) + せる', '[{"jp": "子供を遊ばせます。", "ko": "아이를 놀게 합니다."}, {"jp": "弟に買い物をさせます。", "ko": "남동생에게 쇼핑을 시킵니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('れる / られる', '수동동사 (보통형)', 'V(내이형) + れる', '[{"jp": "先生に褒められました。", "ko": "선생님께 칭찬받았습니다."}, {"jp": "泥棒に財布を盗まれました。", "ko": "도둑에게 지갑을 도둑맞았습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('お ~ になる', '존경어 (기초)', 'お+V(ます형)+になる', '[{"jp": "先生がお帰りになります。", "ko": "선생님이 귀가하십니다."}, {"jp": "何をお読みになりますか?", "ko": "무엇을 읽으십니까?"}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('お ~ する / いたす', '겸양어 (기초)', 'お+V(ます형)+する', '[{"jp": "お荷物をお持ちします。", "ko": "짐을 들어 드리겠습니다."}, {"jp": "お待ちいたしました。", "ko": "기다렸습니다 (겸양)."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('くださいませ', '정중한 의뢰/환영', 'V(て형) + くださいませ', '[{"jp": "少々お待ちくださいませ。", "ko": "잠시 기다려 주십시오."}, {"jp": "どうぞお入りくださいませ。", "ko": "어서 들어오십시오."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('たぶん ~ でしょう', '아마 ~이겠지요 (추측)', '부사 + でしょう', '[{"jp": "たぶん明日は雨でしょう。", "ko": "아마 내일은 비가 오겠지요."}, {"jp": "彼はたぶん来るでしょう。", "ko": "그는 아마 오겠지요."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('ぜひ ~ てください', '꼭 ~해주세요 (강조)', '부사 + てください', '[{"jp": "ぜひうちへ来てください。", "ko": "꼭 저희 집에 놀러 오세요."}, {"jp": "ぜひ読んでください。", "ko": "꼭 읽어 보세요."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('ぜんぜん ~ ない', '전혀 ~하지 않다 (부정 강조)', '부사 + 부정형', '[{"jp": "全然わかりません。", "ko": "전혀 모르겠습니다."}, {"jp": "全然食べませんでした。", "ko": "전혀 먹지 않았습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('なかなか ~ ない', '좀처럼 ~하지 않다 (부정 강조)', '부사 + 부정형', '[{"jp": "なかなかバスが来ません。", "ko": "좀처럼 버스가 오지 않습니다."}, {"jp": "なかなか覚えられません。", "ko": "좀처럼 외워지지 않습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('けっして ~ ない', '결코 ~하지 않다 (강한 부정)', '부사 + 부정형', '[{"jp": "決して忘れません。", "ko": "결코 잊지 않겠습니다."}, {"jp": "決して嘘を言いません。", "ko": "결코 거짓말을 하지 않겠습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('もし / もしかしたら', '혹시 / 만약', '부사', '[{"jp": "もし雨が降ったら行きません。", "ko": "만약 비가 오면 가지 않습니다."}, {"jp": "もしかしたら遅れるかもしれません。", "ko": "혹시 늦을지도 모릅니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('まず', '우선 / 먼저 (순서)', '부사', '[{"jp": "まず顔を洗います。", "ko": "먼저 세수를 합니다."}, {"jp": "まずこれを見てください。", "ko": "우선 이것을 보세요."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('といっしょに', '~와 함께', '명사 + といっしょに', '[{"jp": "家族といっしょに住んでいます。", "ko": "가족과 함께 살고 있습니다."}, {"jp": "友達といっしょに遊びました。", "ko": "친구와 함께 놀았습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('ひとりで', '혼자서', '부사', '[{"jp": "一人で学校へ行きます。", "ko": "혼자서 학교에 갑니다."}, {"jp": "一人で食べます。", "ko": "혼자서 먹습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('とても', '매우 (강조)', '부사', '[{"jp": "とても綺麗ですね。", "ko": "매우 예쁘네요."}, {"jp": "とても寒いです。", "ko": "매우 춥습니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('すこし / ちょっと', '조금 / 좀', '부사', '[{"jp": "少し疲れました。", "ko": "조금 피곤합니다."}, {"jp": "ちょっと待ってください。", "ko": "잠시 기다려 주세요."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('はやく / すぐに', '빨리 / 금방', '부사', '[{"jp": "はやく来てください。", "ko": "빨리 오세요."}, {"jp": "すぐに終わります。", "ko": "금방 끝납니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('ゆっくり / だんだん', '천천히 / 점점', '부사', '[{"jp": "ゆっくり話してください。", "ko": "천천히 말씀해 주세요."}, {"jp": "だんだん暖かくなります。", "ko": "점점 따뜻해집니다."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('よく', '자주 / 잘', '부사', '[{"jp": "よく映画を見ます。", "ko": "자주 영화를 봅니다."}, {"jp": "よく勉強しましたね。", "ko": "공부 열심히 하셨네요."}]', 5);
INSERT INTO public.grammar (pattern, meaning, connection, examples, jlpt_level) VALUES ('~たら', '~라면 / ~한다면 (가정)', 'V(た형) + ら', '[{"jp": "安かったら買います。", "ko": "싸면 사겠습니다."}, {"jp": "日本へ行ったら連絡します。", "ko": "일본에 가면 연락하겠습니다."}]', 5);